// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: page-wide keys, view floating and copy buttons for delulu-smash. Keys come from window.SHORTCUTS
//          (set from ui/shortcuts.py, the one place they are defined):
//          FULL_SCREEN floats the view (.widget) you are in nearly full screen, or, outside a view,
//          fills the window with your pane (clicks its zoom button). CLOSE (Esc) closes a menu
//          (a full-screen debug panel goes back to the side; the help and debug side panels stay), then a floating view. PALETTE clicks the hidden button that shows or hides the
//          command palette (a search box over every command: type to filter, arrows, Enter; the ones run last come
//          first); in a menu, arrows move between its rows. window.smashPress(keys) runs a shortcut as if its key
//          were pressed where you were (the palette's and the keybindings list's way to run one). TOGGLE_CHAT / TOGGLE_RESULTS / TOGGLE_PYTHON / TOGGLE_VARIABLES / HELP / DEBUG click the
//          bottom bar's pane toggles, ZOOM_CHAT / ZOOM_RESULTS / ZOOM_PYTHON / ZOOM_VARIABLES hidden buttons (data-toggle="zoom-<pane>"), and the title bar's ? and bug icon (data-toggle). A view's float button (render.float_button) and
//          a click outside a floating view work too. reveal(id) scrolls to a chat row, result tab or
//          cell and flashes it (State.reveal). INLINE_EDIT outside a code editor, in a view with a tool
//          form, clicks that view's AI button (render.ai_toggle): the form's "Ask AI" row; CLOSE in
//          that form closes the row. window.perfSnapshot() gives this window's own numbers (JS heap,
//          DOM size, long tasks) to the debug panel's System tab. A clicked link (a widget's or
//          the AI's) opens as a glance: the `web` Browser floating over the app (see below).
// ---------------------------------------------------------------------------
(() => {
  const SHORTCUTS = window.SHORTCUTS || { FULL_SCREEN: "Alt+F", CLOSE: "Escape" };
  // keys matched by position, not by what they type: Shift+` types ~ (Shortcut.ZOOM_TERMINAL)
  const KEY_CODES = { "`": "Backquote" };

  // "Alt+F" -> does this keydown match? Modifiers must match exactly; a letter matches by key position.
  const matches = (event, combo) => {
    const parts = combo.split("+");
    const key = parts.pop();
    const mods = new Set(parts);
    if (event.altKey !== mods.has("Alt") || event.ctrlKey !== mods.has("Ctrl")
      || event.shiftKey !== mods.has("Shift") || event.metaKey !== mods.has("Meta")) return false;
    // a letter, or a key in KEY_CODES, matches by its position (Shift changes what it types)
    if (/^[A-Z]$/.test(key)) return event.code === `Key${key}`;
    return KEY_CODES[key] ? event.code === KEY_CODES[key] : event.key === key;
  };

  // a shortcut's key or its second one (Binding.also in shortcuts.py)
  const ALSO = window.SHORTCUTS_ALSO || {};
  const pressed = (event, name) => Boolean(SHORTCUTS[name] && matches(event, SHORTCUTS[name])) || Boolean(ALSO[name] && matches(event, ALSO[name]));

  let lastTarget = null;
  const paneOf = (node) => (node instanceof Element ? node.closest("[data-pane]") : null);
  const visible = (node) => node && node.isConnected && node.offsetParent !== null;
  const floating = () => document.querySelector(".widget.is-floating");
  // the AI button of the view a node is in, when that view has a tool form (render.ai_toggle)
  const aiToggleOf = (node) => (node instanceof Element && node.isConnected
    ? (node.closest(".widget") || document.createElement("i")).querySelector("[data-ai-toggle]") : null);

  const setFloating = (widget, on) => {
    // a glance (a clicked link, below) put back without docking it is closed: the server
    // closes the `web` tab and puts the layout back (State.close_glance)
    if (!on && widget.dataset.glance) {
      delete widget.dataset.glance;
      document.querySelector('[data-toggle="glance-close"]')?.click();
    }
    widget.classList.toggle("is-floating", on);
    document.body.classList.toggle("has-floating", on);
    // grids size themselves on resize
    window.dispatchEvent(new Event("resize"));
  };
  const toggleFloat = (widget) => {
    const current = floating();
    if (current && current !== widget) setFloating(current, false);
    setFloating(widget, !widget.classList.contains("is-floating"));
  };

  // State.reveal: scroll to an element (a chat row, a result tab, a cell) and flash it. The one
  // navigation of the app (Show in Chat, the debug log's links); the flash is .is-flash in
  // app.css, on the element's [data-flash] part when it has one (eg a result row, not its view)
  window.reveal = (id) => {
    const target = document.getElementById(id);
    if (!target) return;
    const current = floating();
    if (current) setFloating(current, false);
    target.scrollIntoView({ block: "center", inline: "nearest", behavior: "smooth" });
    const row = target.querySelector("[data-flash]") || target;
    row.classList.remove("is-flash");
    void row.offsetWidth; // restart the animation when flashed twice
    row.classList.add("is-flash");
    setTimeout(() => row.classList.remove("is-flash"), 1600);
  };

  // The debug panel's System tab (State.load_perf): this window's own numbers, as rows of
  // {label, value}. Long tasks (the page frozen for over 50 ms) are counted from page load.
  const longTasks = { count: 0, total: 0, worst: 0 };
  try {
    new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        longTasks.count += 1;
        longTasks.total += entry.duration;
        longTasks.worst = Math.max(longTasks.worst, entry.duration);
      }
    }).observe({ type: "longtask", buffered: true });
  } catch { /* not supported: the row says so */ }
  const mb = (bytes) => `${(bytes / 1024 / 1024).toFixed(1)} MB`;
  const span = (ms) => (ms >= 60000 ? `${(ms / 60000).toFixed(0)} min` : ms >= 1000 ? `${(ms / 1000).toFixed(1)} s` : `${Math.round(ms)} ms`);
  window.perfSnapshot = () => {
    const rows = [];
    const add = (label, value) => rows.push({ label, value: String(value) });
    const heap = performance.memory;
    add("JS heap", heap ? `${mb(heap.usedJSHeapSize)} used of ${mb(heap.totalJSHeapSize)} (limit ${mb(heap.jsHeapSizeLimit)})` : "not reported by this browser");
    add("page elements", `${document.getElementsByTagName("*").length.toLocaleString()} DOM nodes`);
    add("long tasks", window.PerformanceObserver
      ? `${longTasks.count} (page frozen over 50 ms), ${span(longTasks.total)} in all, worst ${span(longTasks.worst)}`
      : "not reported by this browser");
    const nav = performance.getEntriesByType("navigation")[0];
    if (nav) add("page load", `${span(nav.domContentLoadedEventEnd)} to ready, ${span(nav.loadEventEnd)} to loaded`);
    add("page open for", span(performance.now()));
    add("files loaded", `${performance.getEntriesByType("resource").length} requests since load`);
    add("code editors", `${document.querySelectorAll(".cm-editor").length} mounted`);
    add("window", `${window.innerWidth} × ${window.innerHeight}, ${navigator.hardwareConcurrency || "?"} cores`);
    return rows;
  };

  document.addEventListener("pointerdown", (event) => {
    if (paneOf(event.target)) lastTarget = event.target;
    if (paneOf(event.target)) mark(paneOf(event.target));
    acted = performance.now();
    // a click outside the floating view puts it back (menus and popups float above it, so not those)
    const current = floating();
    if (current && !current.contains(event.target)
      && !event.target.closest(".menu, .help-panel, .debug-panel, .overlay-backdrop, .palette-backdrop, .cm-tooltip, .gdg-overlay, #portal")) {
      setFloating(current, false);
    }
  }, true);

  // Moving up and down the chat: its two round buttons (.chat-jump in ui.py) and the keys
  // CHAT_UP / CHAT_DOWN (a row at a time) and CHAT_TURN_UP / CHAT_TURN_DOWN (a message you sent
  // at a time). The chat scrolls in reverse (column-reverse), so the newest message is scrollTop 0
  // and scrolling up goes negative. ↓ (.is-scrolled) shows once you scroll up, ↑ (.can-up) while
  // there is chat above. `scroll` doesn't bubble: listen in the capture phase.
  const SCROLLED_UP = 80;
  const CHAT_EDGE = 4;   // px: closer than this to a row's top (or the chat's) is "at" it
  const CHAT_PAD = 14;   // px kept above the row gone to: its hover buttons sit over its top edge
  const updateJump = (chat) => {
    const body = chat.parentElement;
    body.classList.toggle("is-scrolled", Math.abs(chat.scrollTop) > SCROLLED_UP);
    body.classList.toggle("can-up", chat.scrollHeight - chat.clientHeight - Math.abs(chat.scrollTop) > CHAT_EDGE);
  };
  document.addEventListener("scroll", (event) => {
    if (event.target instanceof Element && event.target.matches(".chat-scroll")) updateJump(event.target);
  }, true);
  // an answer growing at the newest message scrolls nothing: watch the chat's size too. The chat
  // mounts after this script, so it is looked for again on a click or a key
  const watchedChats = new WeakSet();
  const watchChats = () => document.querySelectorAll(".chat-scroll").forEach((chat) => {
    if (watchedChats.has(chat) || !chat.firstElementChild) return;
    watchedChats.add(chat);
    const sizes = new ResizeObserver(() => updateJump(chat));
    sizes.observe(chat);
    sizes.observe(chat.firstElementChild);
  });
  document.addEventListener("pointerdown", watchChats, true);
  document.addEventListener("keydown", watchChats, true);
  watchChats();

  // the row being scrolled to (or "start" / "end", the chat's two ends): a second press before the scroll ends goes on from it, not from
  // where the scroll has got to
  let chatJump = null;
  let chatJumpTimer = 0;
  const endChatJump = () => { chatJump = null; };
  document.addEventListener("scrollend", (event) => {
    if (event.target instanceof Element && event.target.matches(".chat-scroll")) endChatJump();
  }, true);
  // step: -1 up, 1 down. turns: stop only at the messages you sent, else at every row (the line
  // of what a turn cost is no stop: it is its answer's last line). Past the first: the top of
  // the chat; past the last: the newest message
  const chatStep = (chat, step, turns) => {
    const top = (row) => row.getBoundingClientRect().top - chat.getBoundingClientRect().top;
    const rows = [...chat.querySelectorAll(turns ? ".chat-items > .bubble.is-user"
      : ".chat-items > :not(.empty, .turn-usage, .agent-progress)")];
    // where the view's top edge is, or will be once the scroll under way ends (a row, an end)
    const items = chat.firstElementChild;
    let from = CHAT_PAD;
    if (chatJump === "start") from += top(items);
    else if (chatJump === "end") from += top(items) + items.offsetHeight - chat.clientHeight;
    else if (chatJump && chat.contains(chatJump)) from = top(chatJump);
    const target = step < 0 ? rows.filter((row) => top(row) < from - CHAT_EDGE).pop()
      : rows.find((row) => top(row) > from + CHAT_EDGE);
    chatJump = target || (step < 0 ? "start" : "end");
    clearTimeout(chatJumpTimer);
    chatJumpTimer = setTimeout(endChatJump, 700);  // a scroll that had nowhere to go ends nothing
    if (target) chat.scrollTo({ top: chat.scrollTop + top(target) - CHAT_PAD, behavior: "smooth" });
    else chat.scrollTo({ top: step < 0 ? -chat.scrollHeight : 0, behavior: "smooth" });
  };
  document.addEventListener("click", (event) => {
    const button = event.target instanceof Element && event.target.closest("[data-chat-bottom], [data-chat-up]");
    if (!button) return;
    const chat = button.closest(".chat-body").querySelector(".chat-scroll");
    if (button.matches("[data-chat-bottom]")) chat.scrollTo({ top: 0, behavior: "smooth" });
    else if (event.shiftKey) chat.scrollTo({ top: -chat.scrollHeight, behavior: "smooth" });
    else chatStep(chat, -1, true);
  });
  // the keys: only while the chat is the pane you are in (in a cell they are the editor's own,
  // CELL_UP / CELL_DOWN), and nothing is open over the page
  document.addEventListener("keydown", (event) => {
    const name = ["CHAT_UP", "CHAT_DOWN", "CHAT_TURN_UP", "CHAT_TURN_DOWN"].find((key) => pressed(event, key));
    if (!name) return;
    const pane = document.querySelector('[data-pane="chat"][data-active]');
    const chat = pane && pane.querySelector(".chat-scroll");
    if (!chat || !visible(chat) || document.querySelector(".palette-backdrop, .overlay-backdrop")) return;
    if (event.target instanceof Element && event.target.closest(".cm-editor")) return;
    event.preventDefault();
    event.stopPropagation();
    chatStep(chat, name.endsWith("UP") ? -1 : 1, name.includes("TURN"));
  }, true);

  // copy buttons (copy_button in ui.py): copy data-copy, show a tick for a moment
  document.addEventListener("click", async (event) => {
    const button = event.target instanceof Element && event.target.closest(".copy-btn");
    if (!button) return;
    try {
      await navigator.clipboard.writeText(button.dataset.copy || "");
      button.classList.add("is-copied");
      setTimeout(() => button.classList.remove("is-copied"), 1400);
    } catch {
      button.title = "Couldn't copy (clipboard blocked)";
    }
  });

  // a glance's float button docks it: it stays as the `web` tab (State.dock_glance)
  const dock = (widget) => {
    if (!widget.dataset.glance) return;
    delete widget.dataset.glance;
    document.querySelector('[data-toggle="glance-dock"]')?.click();
  };
  document.addEventListener("click", (event) => {
    const button = event.target instanceof Element && event.target.closest(".float-btn");
    if (!button) return;
    const widget = button.closest(".widget");
    if (!widget) return;
    // a view's × (render.close_view_button): the server closes it; a floating one is put back
    // here first, without the glance's own close (the server's close covers that too)
    if (button.matches("[data-close-view]")) {
      if (widget.classList.contains("is-floating")) {
        delete widget.dataset.glance;
        setFloating(widget, false);
      }
      return;
    }
    dock(widget);
    toggleFloat(widget);
  });

  // Links open in the app, as a glance (as in Zen): a widget's link (render.link, a.link) or
  // one in the AI's answer (.bubble a) loads in the one `web` Browser tab (State.browse),
  // which then floats over the app. Ctrl / Shift / middle click still opens a real tab; so do
  // buttons drawn as links (.act, eg Open ↗) and links outside widgets and the chat.
  const glanceable = (a) => a.matches("a.link, .bubble a") && !a.matches(".act") && /^https?:/i.test(a.href);
  const glance = (url, verdict) => {
    const form = document.querySelector("form[data-browse]");
    if (!form) return false;
    form.querySelector("[data-browse-url]").value = url;
    // the check's answer (true -> no "Blank?" hint; null -> the hint)
    form.querySelector("[data-browse-frameable]").value = verdict === true ? "true" : "";
    form.requestSubmit();
    // float the `web` Browser once it shows this page (the server redraws it first)
    const until = performance.now() + 8000;
    const tick = () => {
      const widget = document.querySelector('[data-pane="results"] .widget[data-slot="tab:web"]');
      const address = widget && widget.querySelector('input[name="url"]');
      if (widget && visible(widget) && address && address.value === url) {
        widget.dataset.glance = "1";
        if (!widget.classList.contains("is-floating")) {
          const current = floating();
          if (current && current !== widget) setFloating(current, false);
          widget.classList.add("is-floating");
          document.body.classList.add("has-floating");
          window.dispatchEvent(new Event("resize"));
        }
        return;
      }
      if (performance.now() < until) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
    return true;
  };
  // First ask the server whether the site lets a frame show it (GET /frameable, web.frameable;
  // it gives up after 0.5 s): a site that refuses (eg github.com) opens in a real browser tab,
  // while the click still counts as one (the popup blocker allows it); unknown -> the glance.
  const ask = async (url) => {
    const form = document.querySelector("form[data-browse]");
    const endpoint = form && form.dataset.frameableUrl;
    if (!endpoint) return null;
    const stop = new AbortController();
    const timer = setTimeout(() => stop.abort(), 700);
    try {
      const response = await fetch(`${endpoint}?url=${encodeURIComponent(url)}`, { signal: stop.signal });
      return (await response.json()).frameable;
    } catch {
      return null;
    } finally {
      clearTimeout(timer);
    }
  };
  document.addEventListener("click", async (event) => {
    const link = event.target instanceof Element && event.target.closest("a[href]");
    if (!link || !glanceable(link) || event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey) return;
    if (!document.querySelector("form[data-browse]")) return;
    event.preventDefault();
    event.stopPropagation();
    const url = link.href;
    const verdict = await ask(url);
    if (verdict === false) window.open(url, "_blank", "noopener");
    else glance(url, verdict);
  }, true);

  // a menu with a search box (ui.menu_search): typing keeps the rows that have every
  // word and highlights the first; it starts with all rows, when the box takes focus on opening
  // The palette's "recently used": the ids of the last commands run (data-command), newest first,
  // kept in this browser. They are listed after the fixed first rows (data-pinned: help and the
  // panels, commands.PALETTE_FIRST, which keep their place), by CSS order (the rows are React's).
  const PINNED_ORDER = "-100";
  const RECENT_KEY = "delulu-smash.palette.recent";
  const MAX_RECENT = 5;
  const recent = () => {
    try { return JSON.parse(localStorage.getItem(RECENT_KEY) || "[]"); } catch { return []; }
  };
  const remember = (id) => {
    try {
      localStorage.setItem(RECENT_KEY, JSON.stringify([id, ...recent().filter((other) => other !== id)].slice(0, MAX_RECENT)));
    } catch { /* storage blocked: no recents */ }
  };
  // rows as shown: the fixed first rows, recently used, then as written
  const menuRows = (search) => {
    const rows = [...search.closest(".menu").querySelectorAll(".menu-item")];
    return rows.sort((a, b) => Number(a.style.order || 0) - Number(b.style.order || 0));
  };
  const setActive = (rows, row) => {
    rows.forEach((other) => other.classList.toggle("is-active", other === row));
    if (row) row.scrollIntoView({ block: "nearest" });
  };
  const filterMenu = (search) => {
    const menu = search.closest(".menu");
    if (menu.matches("[data-palette]")) {
      const ids = recent();
      menu.querySelectorAll(".menu-item").forEach((row) => {
        const pinned = !!row.dataset.pinned;
        const at = pinned ? -1 : ids.indexOf(row.dataset.command);
        row.style.order = pinned ? PINNED_ORDER : at < 0 ? "" : String(at - MAX_RECENT);
        row.classList.toggle("is-recent", at >= 0);
      });
    }
    const words = search.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
    const rows = menuRows(search);
    rows.forEach((row) => {
      const text = `${row.textContent} ${row.dataset.words || ""}`.toLowerCase();
      row.hidden = !words.every((word) => text.includes(word));
    });
    const shown = rows.filter((row) => !row.hidden);
    setActive(rows, shown[0]);
    menu.classList.toggle("is-empty", shown.length === 0);
  };
  document.addEventListener("click", (event) => {
    const row = event.target instanceof Element && event.target.closest("[data-palette] [data-command]");
    if (row) remember(row.dataset.command);
  }, true);

  // Where you were before a menu took the focus (the palette's search box): what "the result you
  // are in" and "the editor you were in" mean for a command run from it.
  let origin = null;
  let lastEditor = null;
  document.addEventListener("focusin", (event) => {
    if (!(event.target instanceof Element)) return;
    if (event.target.closest(".cm-editor")) lastEditor = event.target;
    if (event.target.matches("[data-menu-search]") && event.relatedTarget instanceof Element) origin = event.relatedTarget;
    // the pane the cursor is in is the active one; where in it is kept for coming back
    const pane = paneOf(event.target);
    if (!pane) return;
    mark(pane);
    // a place of yours: not a button, nor the view or pane itself (where activate falls back to)
    if (!event.target.closest("button") && !event.target.matches(".widget, [data-pane]")) lastIn.set(pane.dataset.pane, event.target);
  });

  // The active pane ([data-active], not shown on screen: the cursor is the only sign): where the cursor is. NEXT_PANE / PREV_PANE
  // move it between the panes shown; a pane you open (key, click, palette) becomes it, as does
  // a Results tab you open; the first pane shown when the active one closes. Something the AI
  // opens never moves the cursor: only what follows your own key or click (YOURS_MS) does.
  // HOME: where the cursor goes in a pane with no place of yours to come back to, the first
  // of its selectors that is shown (Results: a SmashDb console's query box, else the view
  // itself); none (or not there): the pane itself, eg Variables.
  const HOME = {
    chat: [".composer textarea"], python: [".cm-content"], terminal: ["iframe"],
    results: [".db-editor .cm-content", ".widget"],
  };
  const YOURS_MS = 1000;
  const lastIn = new Map();  // pane name -> the element last focused in it
  let acted = 0;  // when you last clicked, or pressed a key that can open something
  const shown = (node) => Boolean(node && node.isConnected && node.getClientRects().length);
  const shownPanes = () => [...document.querySelectorAll("[data-pane]")].filter(shown).sort((a, b) => {
    const [p, q] = [a.getBoundingClientRect(), b.getBoundingClientRect()];
    return p.top - q.top || p.left - q.left;
  });
  const activePane = () => document.querySelector("[data-pane][data-active]");
  function mark(pane) {
    document.querySelectorAll("[data-pane]").forEach((other) => other.toggleAttribute("data-active", other === pane));
  }
  const activate = (pane, retry = true) => {
    mark(pane);
    const name = pane.dataset.pane;
    const last = lastIn.get(name);
    const homes = (HOME[name] || []).map((selector) => [...pane.querySelectorAll(selector)].find(shown));
    const spot = shown(last) && pane.contains(last) ? last : homes.find(Boolean);
    const target = spot || pane;
    if (target.tabIndex < 0) target.tabIndex = -1;  // a pane or a view takes the focus only this way
    target.focus({ preventScroll: true });
    if (target.tagName === "IFRAME") focusFrame(target);
    // the best place may not be there yet (the Terminal's frame, a console's editor: they mount
    // a moment after the pane shows): once more, if you are still where this put you
    if (retry && !(spot && spot === last) && HOME[name] && !homes[0]) {
      setTimeout(() => activePane() === pane && shown(pane) && document.activeElement === target && activate(pane, false), 400);
    }
  };
  const cycle = (step) => {
    const panes = shownPanes();
    if (panes.length) activate(panes[(panes.indexOf(activePane()) + step + panes.length) % panes.length]);
  };
  const resultSlot = () => ([...document.querySelectorAll('[data-pane="results"] .widget')].find(shown) || { dataset: {} }).dataset.slot || "";
  let before = new Set();
  let slot = "";
  let queued = false;
  const panesChanged = () => {
    queued = false;
    const now = shownPanes();
    const opened = now.filter((pane) => !before.has(pane));
    const tab = resultSlot();
    const newTab = tab && tab !== slot;
    before = new Set(now);
    slot = tab;
    const yours = performance.now() - acted < YOURS_MS;
    if (yours && opened.length) return activate(opened[0]);
    if (yours && newTab) return activate(document.querySelector('[data-pane="results"]'));
    if (now.length && !now.includes(activePane())) activate(now[0]);
  };
  new MutationObserver(() => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(panesChanged);
  }).observe(document.documentElement, { subtree: true, childList: true, attributes: true, attributeFilter: ["class"] });

  // Run a shortcut by its keys ("Alt+F"), as if pressed where you were. Waits a moment, for the
  // menu that asked to be gone and the focus to be back.
  const EDITOR_KEYS = new Set([SHORTCUTS.INLINE_EDIT].filter(Boolean));
  window.smashPress = (keys, from) => setTimeout(() => {
    let target = [from, origin, document.activeElement].find((node) => node instanceof Element && node.isConnected);
    if (EDITOR_KEYS.has(keys) && !(target && target.closest(".cm-editor"))) {
      // an editor's key, run from outside one: the result with a tool form you were in (the key
      // fills its inputs there), else the editor you were last in, else the first cell
      const inForm = [target, lastTarget].find((node) => aiToggleOf(node) && !node.closest(".cm-editor"));
      target = inForm || [lastEditor, document.querySelector(".cell .cm-content")].find((node) => visible(node));
    }
    if (!target) target = document.body;
    if (target !== document.body) target.focus();
    const parts = keys.split("+");
    const key = parts.pop();
    const letter = /^[A-Z]$/.test(key);
    const shift = parts.includes("Shift");
    target.dispatchEvent(new KeyboardEvent("keydown", {
      key: letter ? (shift ? key : key.toLowerCase()) : key,
      code: letter ? `Key${key}` : KEY_CODES[key] || key,
      keyCode: letter ? key.charCodeAt(0) : 0,
      altKey: parts.includes("Alt"), ctrlKey: parts.includes("Ctrl"), shiftKey: shift, metaKey: parts.includes("Meta"),
      bubbles: true, cancelable: true,
    }));
  }, 80);
  // A robot button (render.inline_ai_button; data-inline-ai: where, inside its pane or view):
  // the inline chat there, as INLINE_EDIT pressed in it. In the editor you were last in when
  // it is one of them, else the first shown; a framed pane's is in its strip (frame_ask.js).
  document.addEventListener("click", (event) => {
    const button = event.target.closest?.("[data-inline-ai]");
    const scope = button && button.closest(".widget, [data-pane]");
    if (!scope) return;
    const spots = [...scope.querySelectorAll(button.dataset.inlineAi)].filter(visible);
    const spot = spots.includes(lastEditor) ? lastEditor : spots[0];
    if (!spot) return;
    if (spot.tagName !== "IFRAME") return window.smashPress(SHORTCUTS.INLINE_EDIT, spot);
    // a framed pane (the Terminal): its box is in the pane's title strip (assets/frame_ask.js)
    window.smashFrameAsk?.toggle(spot.closest("[data-pane]"));
  });
  document.addEventListener("input", (event) => {
    if (event.target.matches?.("[data-menu-search]")) filterMenu(event.target);
  });
  document.addEventListener("focusin", (event) => {
    if (event.target.matches?.("[data-menu-search]")) filterMenu(event.target);
  });

  // The Terminal pane (terminal.py) frames a page on the backend's origin, so its keys don't
  // reach this page: it sends its own pane keys here instead, to run as if pressed here.
  const TERMINAL_KEYS = new Set([SHORTCUTS.TOGGLE_TERMINAL, SHORTCUTS.ZOOM_TERMINAL, SHORTCUTS.CLOSE_ALL, SHORTCUTS.NEXT_PANE, SHORTCUTS.PREV_PANE].filter(Boolean));
  window.addEventListener("message", (event) => {
    const data = event.data;
    if (!data || data.type !== "delulu-press" || !TERMINAL_KEYS.has(data.keys)) return;
    acted = performance.now();
    if (data.keys === SHORTCUTS.NEXT_PANE || data.keys === SHORTCUTS.PREV_PANE) return cycle(data.keys === SHORTCUTS.NEXT_PANE ? 1 : -1);
    const name = { [SHORTCUTS.ZOOM_TERMINAL]: "zoom-terminal", [SHORTCUTS.CLOSE_ALL]: "close-all" }[data.keys] || "terminal";
    document.querySelector(`[data-toggle="${name}"]`)?.click();
    focusTerminalSoon({ terminal: "TOGGLE_TERMINAL", "zoom-terminal": "ZOOM_TERMINAL", "close-all": "CLOSE_ALL" }[name]);
  });
  // The Terminal's frame: focusing the iframe alone may leave its page's shell without the
  // keys (its window's focus event doesn't always fire), so ask its page to focus it (terminal.py)
  function focusFrame(frame) {
    frame.contentWindow?.postMessage({ type: "delulu-focus" }, "*");
  }
  // the cursor into a framed pane's page (frame_ask.js uses it too)
  window.smashFocusFrame = (frame) => { frame.focus(); focusFrame(frame); };
  // after a key shows the Terminal: put the cursor in it (its page focuses the shell); after one
  // hides it: back to the page, so the app's keys work again
  function focusTerminalSoon(name) {
    if (name !== "TOGGLE_TERMINAL" && name !== "ZOOM_TERMINAL" && name !== "CLOSE_ALL") return;
    setTimeout(() => {
      const frame = document.querySelector('[data-pane="terminal"] iframe');
      if (frame && visible(frame)) { frame.focus(); focusFrame(frame); }
      else if (document.activeElement && document.activeElement.tagName === "IFRAME") document.activeElement.blur();
    }, 400);
  }

  // capture phase, so it also works while typing in a code cell or the chat box
  document.addEventListener("keydown", (event) => {
    // a key that can open something (not plain typing): what it opens gets the cursor
    if (event.altKey || event.ctrlKey || event.metaKey || event.key === "Enter") acted = performance.now();
    if (matches(event, SHORTCUTS.CLOSE)) {
      // the top layer only: the palette (above everything), then a menu or panel
      const palette = document.querySelector(".palette-backdrop");
      // the debug panel in full screen goes back to the side first; the next Escape closes it
      const debugFull = !palette && document.querySelector('.debug-panel.is-full [data-toggle="debug-full"]');
      if (debugFull) {
        event.preventDefault();
        event.stopPropagation();
        debugFull.click();
        return;
      }
      const backdrop = palette || document.querySelector(".overlay-backdrop");
      const current = floating();
      // in a widget with its Ask AI box open (in its bar, render.strip_ask_box): close it first,
      // as its lit ✨ does (an open choice list closes itself, assets/choice.js)
      const widget = !backdrop && event.target instanceof Element && !event.target.closest(".choice")
        && event.target.closest(".widget");
      const askClose = widget && widget.querySelector("[data-ask-box]") && aiToggleOf(event.target);
      if (askClose) {
        event.preventDefault();
        event.stopPropagation();
        askClose.click();
        return;
      }
      if (!backdrop && !current) return;
      event.preventDefault();
      event.stopPropagation();
      if (backdrop) backdrop.click();
      else setFloating(current, false);
      return;
    }
    // in a menu's search box: arrows move the highlighted row, Enter picks it
    if (event.target instanceof Element && event.target.matches("[data-menu-search]")) {
      const shown = menuRows(event.target).filter((row) => !row.hidden);
      const at = shown.findIndex((row) => row.classList.contains("is-active"));
      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        event.stopPropagation();
        const next = shown[(at + (event.key === "ArrowDown" ? 1 : -1) + shown.length) % shown.length];
        setActive(shown, next);
        return;
      }
      if (event.key === "Enter") {
        event.preventDefault();
        event.stopPropagation();
        if (shown[at]) shown[at].click();
        return;
      }
    }
    // in a menu: arrows move between its rows (Enter runs the focused one, as any button)
    const item = document.activeElement instanceof Element && document.activeElement.closest(".menu .menu-item");
    if (item && (event.key === "ArrowDown" || event.key === "ArrowUp")) {
      event.preventDefault();
      event.stopPropagation();
      const items = [...item.closest(".menu").querySelectorAll(".menu-item")];
      const next = items.indexOf(item) + (event.key === "ArrowDown" ? 1 : -1);
      items[(next + items.length) % items.length].focus();
      return;
    }
    const step = pressed(event, "NEXT_PANE") ? 1 : pressed(event, "PREV_PANE") ? -1 : 0;
    if (step) {
      event.preventDefault();
      event.stopPropagation();
      return cycle(step);
    }
    const toggle = [["TOGGLE_CHAT", "chat"], ["TOGGLE_RESULTS", "results"], ["TOGGLE_PYTHON", "python"], ["TOGGLE_VARIABLES", "variables"], ["TOGGLE_TERMINAL", "terminal"], ["TOGGLE_PYTHON_VARIABLES", "python-variables"], ["CLOSE_ALL", "close-all"],
      ["ZOOM_CHAT", "zoom-chat"], ["ZOOM_RESULTS", "zoom-results"], ["ZOOM_PYTHON", "zoom-python"], ["ZOOM_VARIABLES", "zoom-variables"], ["ZOOM_TERMINAL", "zoom-terminal"],
      ["HELP", "help"], ["DEBUG", "debug"], ["PALETTE", "palette"]]
      .find(([name]) => pressed(event, name));
    if (toggle) {
      const button = document.querySelector(`[data-toggle="${toggle[1]}"]`);
      if (button) {
        event.preventDefault();
        event.stopPropagation();
        button.click();
        focusTerminalSoon(toggle[0]);
      }
      return;
    }
    if (SHORTCUTS.INLINE_EDIT && matches(event, SHORTCUTS.INLINE_EDIT)) {
      // in a code editor it is the editor's own key (inline_edit.jsx); elsewhere, in a view with a
      // tool form, it opens that form's "Ask AI" row
      if (event.target instanceof Element && event.target.closest(".cm-editor")) return;
      const spot = [event.target, document.activeElement, lastTarget].find((node) => aiToggleOf(node));
      const button = aiToggleOf(floating()) || aiToggleOf(spot);
      if (!button || !visible(button)) return;
      event.preventDefault();
      event.stopPropagation();
      button.click();
      return;
    }
    if (!matches(event, SHORTCUTS.FULL_SCREEN)) return;
    event.preventDefault();
    event.stopPropagation();
    // the debug panel is over the page while open: it is what goes full screen
    const debugFull = document.querySelector('.debug-panel [data-toggle="debug-full"]');
    if (debugFull) return debugFull.click();
    const current = floating();
    if (current) {
      dock(current);  // a glance put back by the key is kept, as by its float button
      return setFloating(current, false);
    }
    // where you are: the focused element, else the last thing clicked
    const here = [document.activeElement, lastTarget].find((node) => visible(paneOf(node)));
    const widget = here && here.closest(".widget");
    if (widget) return toggleFloat(widget);
    const zoomed = document.querySelector(".zoom-btn.is-on");
    const pane = here && paneOf(here);
    const button = zoomed || (pane && pane.querySelector(".zoom-btn")) || document.querySelector("[data-pane] .zoom-btn");
    if (button) button.click();
  }, true);
})();
